import json

import yaml

from prompty.model import FinalOutputPolicyRequest


def test_load_json_finaloutputpolicyrequest():
    json_data = r"""
    {
      "sessionId": "sample",
      "turnId": "sample",
      "iteration": 1,
      "messages": []
    }
    """
    data = json.loads(json_data, strict=False)
    instance = FinalOutputPolicyRequest.load(data)
    assert instance is not None
    assert instance.session_id == "sample"
    assert instance.turn_id == "sample"
    assert instance.iteration == 1


def test_load_yaml_finaloutputpolicyrequest():
    yaml_data = r"""
    sessionId: sample
    turnId: sample
    iteration: 1
    messages: []

    """
    data = yaml.load(yaml_data, Loader=yaml.FullLoader)
    instance = FinalOutputPolicyRequest.load(data)
    assert instance is not None
    assert instance.session_id == "sample"
    assert instance.turn_id == "sample"
    assert instance.iteration == 1


def test_roundtrip_json_finaloutputpolicyrequest():
    """Test that load -> save -> load produces equivalent data."""
    json_data = r"""
    {
      "sessionId": "sample",
      "turnId": "sample",
      "iteration": 1,
      "messages": []
    }
    """
    original_data = json.loads(json_data, strict=False)
    instance = FinalOutputPolicyRequest.load(original_data)
    saved_data = instance.save()
    reloaded = FinalOutputPolicyRequest.load(saved_data)
    assert reloaded is not None
    assert reloaded.session_id == "sample"
    assert reloaded.turn_id == "sample"
    assert reloaded.iteration == 1


